import ast
import importlib
import inspect
from pathlib import Path

def numeric_text(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        return repr(node.value)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
        inner = numeric_text(node.operand)
        if inner is not None:
            return ('-' if isinstance(node.op, ast.USub) else '') + inner
    return None

def money_node(amount_node, currency):
    text = numeric_text(amount_node)
    if text is None:
        return amount_node
    return ast.Call(
        func=ast.Name(id='Money', ctx=ast.Load()),
        args=[
            ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()), args=[ast.Constant(value=text)], keywords=[]),
            ast.Constant(value=currency),
        ],
        keywords=[],
    )

def decimal_node(node):
    text = numeric_text(node)
    if text is None:
        return node
    return ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()), args=[ast.Constant(value=text)], keywords=[])

def wrap_numbers_in(node, factory):
    if isinstance(node, (ast.List, ast.Tuple)):
        elts = [wrap_numbers_in(e, factory) for e in node.elts]
        if isinstance(node, ast.List):
            return ast.List(elts=elts, ctx=ast.Load())
        return ast.Tuple(elts=elts, ctx=ast.Load())
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        return factory(node)
    return node

def call_currency(call):
    vals = [a.value for a in call.args if isinstance(a, ast.Constant) and isinstance(a.value, str)]
    return vals[-1] if vals else 'USD'

class TestTransformer(ast.NodeTransformer):
    def __init__(self, funcs, sigs):
        self.funcs = funcs
        self.sigs = sigs

    def visit_AssertEqual(self, node):
        call = node.left if isinstance(node.left, ast.Call) else None
        if call and isinstance(call.func, ast.Name) and call.func.id in self.funcs:
            name = call.func.id
            sig = self.sigs[name]
            currency = call_currency(call)
            params = list(sig.parameters.values())
            new_args = []
            for i, arg in enumerate(call.args):
                ann = params[i].annotation if i < len(params) else inspect._empty
                if ann is Money:
                    arg = money_node(arg, currency)
                elif ann is Decimal:
                    arg = decimal_node(arg)
                elif ann is list:
                    arg = wrap_numbers_in(arg, lambda n: money_node(n, currency))
                new_args.append(arg)
            call.args = new_args
            # Transform expected value according to the function's return annotation.
            ret = sig.return_annotation
            if len(node.comparators) == 1:
                expected = node.comparators[0]
                if ret is Money:
                    expected = wrap_numbers_in(expected, lambda n: money_node(n, currency))
                elif ret is list:
                    expected = wrap_numbers_in(expected, lambda n: money_node(n, currency))
                node.comparators[0] = expected
        self.generic_visit(node)
        return node

for path in sorted(Path('tests').glob('test_*.py')):
    if path.name == 'test_rates.py':
        continue
    tree = ast.parse(path.read_text(), filename=str(path))
    funcs = {}
    for node in tree.body:
        if isinstance(node, ast.ImportFrom) and node.module and node.module.startswith('ledgerly.'):
            module = importlib.import_module(node.module)
            for alias in node.names:
