from ledgerly.money import Money

def numeric_text(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        return repr(node.value)
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.USub, ast.UAdd)):
        inner = numeric_text(node.operand)
        if inner is not None:
            return ('-' if isinstance(node.op, ast.USub) else '') + inner
    return None

def money_node(amount_node, currency):
    text = numeric_text(amount_node)
    if text is None:
        return amount_node
    return ast.Call(
        func=ast.Name(id='Money', ctx=ast.Load()),
        args=[
            ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()), args=[ast.Constant(value=text)], keywords=[]),
            ast.Constant(value=currency),
        ],
        keywords=[],
    )

def decimal_node(node):
    text = numeric_text(node)
    if text is None:
        return node
    return ast.Call(func=ast.Name(id='Decimal', ctx=ast.Load()), args=[ast.Constant(value=text)], keywords=[])

def wrap_numbers_in(node, factory):
    if isinstance(node, (ast.List, ast.Tuple)):
        elts = [wrap_numbers_in(e, factory) for e in node.elts]
        if isinstance(node, ast.List):
            return ast.List(elts=elts, ctx=ast.Load())
        return ast.Tuple(elts=elts, ctx=ast.Load())
    if isinstance(node, ast.Constant) and isinstance(node.value, (int, float)) and not isinstance(node.value, bool):
        return factory(node)
    return node

def call_currency(call):
    vals = [a.value for a in call.args if isinstance(a, ast.Constant) and isinstance(a.value, str)]
    return vals[-1] if vals else 'USD'

class TestTransformer(ast.NodeTransformer):
    def __init__(self, funcs):
        self.funcs = funcs

    def visit_Call(self, node):
        is_assert = isinstance(node.func, ast.Attribute) and node.func.attr == 'assertEqual'
        if is_assert and len(node.args) == 2:
            call, expected = node.args
            if isinstance(call, ast.Call) and isinstance(call.func, ast.Name) and call.func.id in self.funcs:
                name = call.func.id
                sig = self.funcs[name]
                currency = call_currency(call)
                params = list(sig.parameters.values())
                new_args = []
                for i, arg in enumerate(call.args):
                    ann = params[i].annotation if i < len(params) else inspect._empty
                    if ann is Money:
