import ast, subprocess
from pathlib import Path

def funcs(text):
    tree = ast.parse(text)
    out = {}
    for n in tree.body:
        if isinstance(n, ast.FunctionDef):
            args = n.args
            names = [a.arg for a in args.posonlyargs + args.args]
            defaults = [ast.unparse(d) for d in args.defaults]
            out[n.name] = (names, defaults)
        elif isinstance(n, ast.ClassDef):
            for m in n.body:
                if isinstance(m, ast.FunctionDef) and m.name == '__init__':
                    args = m.args
                    names = [a.arg for a in args.args]
                    defaults = [ast.unparse(d) for d in args.defaults]
                    out[n.name + '.__init__'] = (names, defaults)
    return out

for p in sorted(Path('ledgerly').glob('*/*.py')):
    if p.name == '__init__.py' or p.parent.name == '_gen' or p.name in ('money.py',):
        continue
    old = subprocess.check_output(['git','show','HEAD:'+str(p)], text=True)
    try:
        new = p.read_text()
    except FileNotFoundError:
        continue
    fo, fn = funcs(old), funcs(new)
    if set(fo) != set(fn):
        print('function set changed', p, set(fo)-set(fn), set(fn)-set(fo))
    for name in set(fo) & set(fn):
        if fo[name] != fn[name]:
            print('signature changed', p, name, fo[name], fn[name])
for p in sorted(Path('tests').glob('test_*.py')):
    old = subprocess.check_output(['git','show','HEAD:'+str(p)], text=True)
    new = p.read_text()
    fo, fn = funcs(old), funcs(new)
    if set(fo) != set(fn):
        print('test function set changed', p, set(fo)-set(fn), set(fn)-set(fo))
print('signature audit done')
